async function saveFilterSet(state){const name=prompt('Filter set name');if(!name?.trim())return;const x=await api('/filter-presets',{method:'POST',body:JSON.stringify({name:name.trim(),state})});prefs.activePreset=x.id;await loadPresets();savePreferences();toast('Filter set saved')}
