// back to a plain text box with no suggestions.
function conditionValueListID(field){return{tag:'conditionTagOptions',actress:'conditionActressOptions',studio:'conditionStudioOptions',label:'conditionLabelOptions'}[field]||''}
// populateConditionOptions fills the tag/actress datalists shared by every
// condition row from the currently loaded releases, mirroring how
