// "undefined", which is what previously showed up in a fresh Value field
// and, if left in place, made every applied filter search for that literal
// text and match nothing.
const releaseConditionFields=[['title','Title'],['tag','Tag'],['actress','Actress'],['description','Description'],['studio','Studio'],['label','Label'],['duration','Duration'],['o_count','O Count (StashApp)'],['play_count','Play Count (StashApp)'],['last_o_count','Last O count date (StashApp)'],['last_played','Last Played (StashApp)'],['added_at','Date added'],['updated_at','Date updated'],['release_date','Release Date'],['watchlist','Watchlist'],['downloaded','Downloaded'],['download_started','Download started'],['download_failed','Download failed'],['local','Locally available (StashApp)'],['monitored','Monitored']];
function releaseConditionKind(field){if(['duration','o_count','play_count'].includes(field))return'numeric';if(['last_o_count','last_played','added_at','updated_at','release_date'].includes(field))return'date';if(['watchlist','downloaded','download_started','download_failed','local','monitored'].includes(field))return'bool';return'text'}
function updateConditionRow(row){const field=row.querySelector('[name=field]').value,kind=releaseConditionKind(field),value=row.querySelector('[name=value]'),boolValue=row.querySelector('[name=boolValue]'),op=row.querySelector('[name=op]'),exact=row.querySelector('[data-toggle=exact]'),wildcard=row.querySelector('[data-toggle=wildcard]'),listID=conditionValueListID(field);value.hidden=kind==='bool';boolValue.hidden=kind!=='bool';value.type=kind==='numeric'?'number':kind==='date'?'date':'text';value.step=kind==='numeric'?'any':'';op.hidden=kind!=='numeric'&&kind!=='date';if(kind==='numeric')op.innerHTML='<option value="gte">at least / minimum</option><option value="lte">at most / maximum</option><option value="eq">equals</option><option value="gt">greater than</option><option value="lt">less than</option>';if(kind==='date')op.innerHTML='<option value="after">after</option><option value="before">before</option>';exact.hidden=wildcard.hidden=kind!=='text';if(listID)value.setAttribute('list',listID);else value.removeAttribute('list')}
function conditionRow(c={},container=conditions){const n=document.createElement('div');n.className='condition';n.innerHTML=`<select name="field">${releaseConditionFields.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select><input name="value" type="text" placeholder="Value" autocomplete="off"><select name="boolValue" hidden><option value="true">Yes</option><option value="false">No</option></select><select name="op" hidden></select><label data-toggle="exact"><input name="exact" type="checkbox"> Exact</label><label data-toggle="wildcard"><input name="wildcard" type="checkbox"> Wildcard</label><button type="button">×</button>`;const fieldEl=n.querySelector('[name=field]'),valueEl=n.querySelector('[name=value]');fieldEl.value=c.field||'title';n.querySelector('[name=exact]').checked=!!c.exact;n.querySelector('[name=wildcard]').checked=!!c.wildcard;updateConditionRow(n);valueEl.value=c.value||'';n.querySelector('[name=boolValue]').value=c.value==='false'?'false':'true';if(c.op)n.querySelector('[name=op]').value=c.op;fieldEl.onchange=()=>updateConditionRow(n);valueEl.oninput=()=>{const id=conditionValueListID(fieldEl.value);if(id)populateMetadataOptions(fieldEl.value,document.getElementById(id),valueEl.value)};n.querySelector('button').onclick=()=>n.remove();container.append(n)}
// normalizeGroupedExpression normalizes either shape of a SearchExpression
// (TODO-2.0 Task A "AND/OR condition groups") into {logic, groups:[...]}
// for editing in a Conditions dialog: the new grouped shape passes through
// as-is; a legacy flat shape (top-level "conditions", no "groups" - from a
// preset/URL saved before this feature existed) becomes a single implicit
// group using the old top-level logic, exactly mirroring how the backend
// (releaseFilterWhere/stashMissingFilterWhere) interprets the same legacy
// shape, so editing and re-saving an old preset doesn't change what it
// matches. Shared by both the Release Library and Missing Library Files
// Conditions dialogs.
function normalizeGroupedExpression(expr){expr=expr||{};if(expr.groups?.length)return{logic:expr.logic||'and',groups:expr.groups};if(expr.conditions?.length)return{logic:'and',groups:[{logic:expr.logic||'and',conditions:expr.conditions}]};return{logic:expr.logic||'and',groups:[]}}
// conditionGroupEl renders one AND/OR condition group: its own Match
// (AND/OR) select over its own condition rows, a "+ Condition" button
// scoped to this group, and a "Remove group" button. Mirrors conditionRow's
// tolerance of a partial/empty group object.
function conditionGroupEl(g={}){const n=document.createElement('div');n.className='conditionGroup';n.innerHTML=`<div class="conditionGroupHeader"><label>Match<select name="groupLogic"><option value="and">All (AND)</option><option value="or">Any (OR)</option></select></label><button type="button" class="removeGroup" title="Remove this group">🗑 Remove group</button></div><div class="groupConditions"></div><button type="button" class="addConditionToGroup">+ Condition</button>`;n.querySelector('[name=groupLogic]').value=g.logic||'and';const rows=n.querySelector('.groupConditions');(g.conditions?.length?g.conditions:[{}]).forEach(c=>conditionRow(c,rows));n.querySelector('.addConditionToGroup').onclick=()=>conditionRow({},rows);n.querySelector('.removeGroup').onclick=()=>{n.remove();if(!conditions.children.length)appendConditionGroup()};return n}
function appendConditionGroup(g){conditions.append(conditionGroupEl(g))}
function openConditions(){conditions.innerHTML='';populateConditionOptions();const expr=normalizeGroupedExpression(prefs.searchExpression);conditionsForm.elements.logic.value=expr.logic;(expr.groups.length?expr.groups:[{logic:'and',conditions:[{}]}]).forEach(appendConditionGroup);conditionsDialog.showModal()}
function expressionFromForm(){const groups=[...conditions.querySelectorAll('.conditionGroup')].map(g=>({logic:g.querySelector('[name=groupLogic]').value,conditions:[...g.querySelectorAll('.condition')].map(n=>{const field=n.querySelector('[name=field]').value,kind=releaseConditionKind(field);if(kind==='bool')return{field,value:n.querySelector('[name=boolValue]').value};const value=n.querySelector('[name=value]').value.trim();if(!value)return null;if(kind==='numeric'||kind==='date')return{field,value,op:n.querySelector('[name=op]').value};return{field,value,exact:n.querySelector('[name=exact]').checked,wildcard:n.querySelector('[name=wildcard]').checked}}).filter(Boolean)})).filter(g=>g.conditions.length);return{logic:conditionsForm.elements.logic.value,groups}}
// ---- Missing Library Files (TODO-2.0 Phase 2) - StashApp scenes whose
// underlying video file was lost. Filters/pagination mirror the Releases
