let missingRows=[],missingSelection=new Set(),missingPage=0;
function missingStatusLabel(s){return{missing:'Missing',retrieving:'Retrieving',retrieve_failed:'Retrieve Failed',retrieved:'Retrieved',monitored:'Monitored',downloading:'Downloading',downloaded:'Downloaded',failed:'Failed'}[s]||s||'Unknown'}
// missingFieldKind drives which controls a condition row shows: text
