function missingFieldKind(field){if(field==='o_count'||field==='play_count')return'numeric';if(field==='last_played')return'date';if(field==='has_javlibrary_url'||field==='has_db_entry')return'bool';return'text'}
function updateMissingConditionRow(row){const field=row.querySelector('[name=field]').value,kind=missingFieldKind(field),value=row.querySelector('[name=value]'),boolValue=row.querySelector('[name=boolValue]'),op=row.querySelector('[name=op]'),exact=row.querySelector('[data-toggle=exact]'),wildcard=row.querySelector('[data-toggle=wildcard]');value.hidden=kind==='bool';boolValue.hidden=kind!=='bool';value.type=kind==='numeric'?'number':kind==='date'?'date':'text';op.hidden=kind!=='numeric'&&kind!=='date';if(kind==='numeric')op.innerHTML='<option value="gte">at least</option><option value="lte">at most</option><option value="eq">equals</option><option value="gt">greater than</option><option value="lt">less than</option>';if(kind==='date')op.innerHTML='<option value="after">after</option><option value="before">before</option>';exact.hidden=field!=='studio';wildcard.hidden=!(field==='path'||field==='studio'||field==='tag')}
function missingConditionRow(c={},container=missingConditionRows){const n=document.createElement('div');n.className='condition missingCondition';n.innerHTML=`<select name="field"><option value="path">Path</option><option value="studio">Studio</option><option value="tag">Tag</option><option value="o_count">O-Counter</option><option value="play_count">Play Count</option><option value="last_played">Last Played</option><option value="has_javlibrary_url">Has JavLibrary URL</option><option value="has_db_entry">Already in JAVBeacon database</option></select><input name="value" type="text" placeholder="Value"><select name="boolValue" hidden><option value="true">Yes</option><option value="false">No</option></select><select name="op" hidden></select><label class="check compact" data-toggle="exact"><input name="exact" type="checkbox"> Exact</label><label class="check compact" data-toggle="wildcard"><input name="wildcard" type="checkbox"> Wildcard</label><button type="button">×</button>`;const fieldEl=n.querySelector('[name=field]');fieldEl.value=c.field||'path';n.querySelector('[name=exact]').checked=!!c.exact;n.querySelector('[name=wildcard]').checked=!!c.wildcard;updateMissingConditionRow(n);n.querySelector('[name=value]').value=c.value||'';n.querySelector('[name=boolValue]').value=c.value==='false'?'false':'true';if(c.op)n.querySelector('[name=op]').value=c.op;fieldEl.onchange=()=>updateMissingConditionRow(n);n.querySelector('button').onclick=()=>n.remove();container.append(n)}
// missingConditionGroupEl mirrors conditionGroupEl (see its doc comment)
// for the Missing Library Files Conditions dialog's field set.
function missingConditionGroupEl(g={}){const n=document.createElement('div');n.className='conditionGroup';n.innerHTML=`<div class="conditionGroupHeader"><label>Match<select name="groupLogic"><option value="and">All (AND)</option><option value="or">Any (OR)</option></select></label><button type="button" class="removeGroup" title="Remove this group">🗑 Remove group</button></div><div class="groupConditions"></div><button type="button" class="addConditionToGroup">+ Condition</button>`;n.querySelector('[name=groupLogic]').value=g.logic||'and';const rows=n.querySelector('.groupConditions');(g.conditions?.length?g.conditions:[{}]).forEach(c=>missingConditionRow(c,rows));n.querySelector('.addConditionToGroup').onclick=()=>missingConditionRow({},rows);n.querySelector('.removeGroup').onclick=()=>{n.remove();if(!missingConditionRows.children.length)appendMissingConditionGroup()};return n}
