function openMissingConditions(){missingConditionRows.innerHTML='';const expr=normalizeGroupedExpression(prefs.missingSearchExpression);missingConditionsForm.elements.logic.value=expr.logic;(expr.groups.length?expr.groups:[{logic:'and',conditions:[{}]}]).forEach(appendMissingConditionGroup);missingConditionsDialog.showModal()}
function missingExpressionFromForm(){const groups=[...missingConditionRows.querySelectorAll('.conditionGroup')].map(g=>({logic:g.querySelector('[name=groupLogic]').value,conditions:[...g.querySelectorAll('.missingCondition')].map(n=>{const field=n.querySelector('[name=field]').value,kind=missingFieldKind(field);if(kind==='bool')return{field,value:n.querySelector('[name=boolValue]').value};const value=n.querySelector('[name=value]').value.trim();if(!value)return null;if(kind==='numeric')return{field,value,op:n.querySelector('[name=op]').value||'gte'};if(kind==='date')return{field,value,op:n.querySelector('[name=op]').value||'after'};return{field,value,exact:n.querySelector('[name=exact]').checked,wildcard:n.querySelector('[name=wildcard]').checked}}).filter(Boolean)})).filter(g=>g.conditions.length);return{logic:missingConditionsForm.elements.logic.value,groups}}
// missingPageSizeLimit parses the free-entry Page size field: "All" (any
// case) requests one page big enough to hold the whole missing-file
// backlog (matching the store's stashMissingMaxLimit cap server-side), a
// blank/non-numeric/non-positive value falls back to the 25 default, and
// anything else is used as-is - this is a plain text input rather than a
// fixed dropdown specifically so a page size outside the usual presets can
// be typed in directly (TODO-2.0 Task A).
function missingPageSizeLimit(){const raw=String(missingPageSize?.value??'').trim();if(/^all$/i.test(raw))return 5000;const n=parseInt(raw,10);return Number.isFinite(n)&&n>0?n:25}
function missingQuery(){const limit=missingPageSizeLimit(),params=new URLSearchParams({status:prefs.missingStatus||'',search_expression:JSON.stringify(prefs.missingSearchExpression||{logic:'and',conditions:[]}),sort:prefs.missingSort||'',direction:prefs.missingDirection||'desc',limit:String(limit),offset:String(missingPage*limit)});return{params,limit}}
function syncMissingControls(){$$('#missingView .missingTabs button').forEach(b=>b.classList.toggle('active',(b.dataset.missingStatus||'')===(prefs.missingStatus||'')));missingSortField.value=prefs.missingSort||'';missingSortDirection.textContent=(prefs.missingDirection||'desc')==='asc'?'↑':'↓';missingPageSize.value=prefs.missingPageSize||25}
// missingRowCard mirrors the Release Library card's and Notifications
// list's click-through convention: when a scene is linked to a
// JAVBeacon release, its cover (and title) open that release's detail
// view exactly like clicking a card does - previously a linked Missing
// Library Files row had no way to reach the release it was matched to at
// all (TODO-2.0 Task A click-through bug fix). An unlinked scene has no
// release to open, so its cover stays a plain (non-clickable) placeholder.
function missingRowCard(x){const openAttr=x.release_id?` onclick="if(!event.ctrlKey&&!event.metaKey&&!event.shiftKey){event.preventDefault();openRelease(${x.release_id})}"`:'',cover=x.release_id?`<a class="missingCoverLink" href="/release/${x.release_id}"${openAttr}><img loading="lazy" src="/covers/${x.release_id}" alt="${attr(x.title)}"></a>`:'<span class="missingCoverPlaceholder">🎬</span>',idLine=x.release_video_id?esc(x.release_video_id):esc(x.code||'Unknown ID'),paths=(x.path?[x.path]:(x.paths||[])).filter(Boolean),tags=(x.tags||[]).slice(0,8).map(t=>`<span class="tag">${esc(t)}</span>`).join(''),details=[x.studio?esc(x.studio):'',x.o_counter?'O:'+x.o_counter:'',x.play_count?'Plays:'+x.play_count:'',validDate(x.last_played_at)?'Last played '+esc(fullDateTime(x.last_played_at)):''].filter(Boolean).join(' · '),title=x.release_id?`<h3 class="missingTitleLink" title="${attr(x.title)} - click to open ${attr(idLine)}"><a href="/release/${x.release_id}"${openAttr}>${esc(x.title)}</a></h3>`:`<h3 title="${attr(x.title)}">${esc(x.title)}</h3>`;return `<article class="notificationItem missingItem ${missingSelection.has(x.id)?'selected':''}"><label class="notificationCheck"><input type="checkbox" ${missingSelection.has(x.id)?'checked':''} onchange="toggleMissingRow(${x.id},this.checked)"></label><div class="notificationCover missingCover">${cover}</div><div class="notificationInfo"><div class="meta"><b>${idLine}</b><span class="missingStatusBadge missingStatus-${esc(x.effective_status)}">${esc(missingStatusLabel(x.effective_status))}</span></div>${title}<small>${details||'—'}</small><div class="notificationTags">${tags}</div><small class="missingPath" title="${attr(paths.join(', '))}">${esc(paths.join(', ')||'No path recorded')}</small></div></article>`}
function updateMissingBulkUI(){const total=missingSelection.size;missingBulk.hidden=total===0;const selectedRows=missingRows.filter(r=>missingSelection.has(r.id));missingSearchAgain.hidden=!selectedRows.some(r=>r.effective_status==='failed'||r.effective_status==='monitored');missingSelectedCount.textContent=`${total} selected`}
function renderMissingList(){missingList.innerHTML=missingRows.map(missingRowCard).join('')||'<div class="empty">No missing scenes match this view.</div>';missingSelectAll.checked=missingRows.length>0&&missingRows.every(r=>missingSelection.has(r.id));missingSelectAll.indeterminate=missingRows.some(r=>missingSelection.has(r.id))&&!missingSelectAll.checked;updateMissingBulkUI()}
function renderMissingPagination(total,limit){const pages=Math.max(1,Math.ceil(total/limit));if(missingPage>pages-1)missingPage=Math.max(0,pages-1);missingPagination.innerHTML=total?`<button ${missingPage<=0?'disabled':''} onclick="changeMissingPage(-1)">‹ Prev</button><span>Page ${missingPage+1} of ${pages} · ${total} total</span><button ${missingPage>=pages-1?'disabled':''} onclick="changeMissingPage(1)">Next ›</button>`:''}
function changeMissingPage(delta){missingPage=Math.max(0,missingPage+delta);loadMissingScenes()}
function toggleMissingRow(id,checked){if(checked)missingSelection.add(id);else missingSelection.delete(id);renderMissingList()}
async function loadMissingScenes(){syncMissingControls();try{const{params,limit}=missingQuery(),[rows,count]=await Promise.all([api('/stash-missing?'+params.toString()),api('/stash-missing/count?'+params.toString())]);missingRows=rows;for(const id of[...missingSelection])if(!missingRows.some(r=>r.id===id))missingSelection.delete(id);renderMissingList();renderMissingPagination(count.total||0,limit)}catch(e){missingList.innerHTML=`<div class="empty">${esc(e.message)}</div>`;missingPagination.innerHTML=''}}
function missingStatusTab(value){prefs.missingStatus=value||'';missingPage=0;savePreferences();loadMissingScenes()}
function renderMissingJobResults(results){missingJobResults.innerHTML=(results||[]).length?`<div class="stack">${results.map(r=>`<div class="row"><b>${esc(r.video_id||('Scene #'+r.scene_id))}</b><span>${esc(r.status)}</span>${r.error?`<small>${esc(r.error)}</small>`:''}</div>`).join('')}</div>`:''}
// refreshMissingScanStatus is a lightweight GET-only status check (no
// dialog) used to populate the summary line when entering the view, in
// case a scan is already running or previously completed.
async function refreshMissingScanStatus(){try{const j=await api('/jobs/stash-missing-scan'),counts=j.scenes?` · ${j.scenes} scenes · ${j.missing||0} missing · ${j.matched||0} matched`:` · ${j.missing||0} recorded missing · ${j.matched||0} matched`;missingScanStatus.textContent=j.running?`Scanning… ${j.processed||0}/${j.scenes||'?'} scenes checked · ${j.missing||0} missing · ${j.matched||0} matched${j.current_item?' · checking '+j.current_item:''}`:j.error?'✕ '+j.error:validDate(j.finished_at)?`Last scan: ${fullDateTime(j.finished_at)}${counts}`:'Not scanned yet.';if(j.running)setTimeout(refreshMissingScanStatus,1500)}catch{}}
function openMissingScopeDialog(){missingScopeForm.elements.scope.value=settings.stash_missing_folder_scope||'';missingScopeDialog.showModal()}async function startScanFromScopeDialog(e){e.preventDefault();const scope=missingScopeForm.elements.scope.value;missingScopeStart.disabled=true;try{const saved=await api('/settings',{method:'PUT',body:JSON.stringify({stash_missing_folder_scope:scope})});settings={...settings,...saved}}catch(err){toast(err.message);missingScopeStart.disabled=false;return}missingScopeStart.disabled=false;missingScopeDialog.close();startMissingScan()}async function clearMissingScan(){if(!confirm('Clear all recorded Missing Library Files results?\n\nThis only clears the recorded list - it does not change anything in StashApp or on disk, and a new scan can rebuild it.'))return;missingClearBtn.disabled=true;try{const j=await api('/stash-missing',{method:'DELETE'});toast(`Cleared ${j.removed||0} result${j.removed===1?'':'s'}`);missingPage=0;loadMissingScenes();refreshMissingScanStatus()}catch(e){toast(e.message)}finally{missingClearBtn.disabled=false}}
async function startMissingScan(){missingJobTitle.textContent='Scanning StashApp for missing files';missingJobStatus.textContent='Starting scan…';missingJobProgress.removeAttribute('value');missingJobResults.innerHTML='';if(!missingJobDialog.open)missingJobDialog.showModal();try{await api('/jobs/stash-missing-scan',{method:'POST'});pollMissingScan()}catch(e){missingJobStatus.textContent='✕ '+e.message;toast(e.message)}}
// pollMissingScan shows live "N of Scenes checked" progress once the scene
// count is known (the scan's first step is just fetching that list from
// StashApp, so the bar stays indeterminate until then) plus the scene
// currently being checked - previously this stayed at a static 0 the
// entire time a scan ran (TODO-2.0 Task A).
async function pollMissingScan(){try{const j=await api('/jobs/stash-missing-scan');if(j.scenes>0){missingJobProgress.max=j.scenes;missingJobProgress.value=j.processed||0}else{missingJobProgress.removeAttribute('value')}missingJobStatus.textContent=j.running?`Scanning… ${j.processed||0}/${j.scenes||'?'} scenes checked · ${j.missing||0} missing · ${j.matched||0} matched${j.current_item?' · checking '+j.current_item:''}`:j.error?'✕ '+j.error:`Scan complete · ${j.scenes||0} scenes checked · ${j.missing||0} missing · ${j.matched||0} matched`;if(j.running){setTimeout(pollMissingScan,1000);return}missingJobProgress.value=missingJobProgress.max||1;refreshMissingScanStatus();if(!j.error)toast(`Scan complete · ${j.missing||0} missing found`);missingPage=0;loadMissingScenes()}catch(e){missingJobStatus.textContent='✕ '+e.message}}
// startMissingRetrieve is the "search and add the release from JavLibrary"
// step - it runs immediately for the current selection rather than being
// queued, matching TODO-2.0 Phase 2's priority-1 intent.
async function startMissingRetrieve(){const ids=[...missingSelection];if(!ids.length)return;missingJobTitle.textContent='Retrieving from JavLibrary';missingJobStatus.textContent='Starting retrieval…';missingJobProgress.removeAttribute('value');missingJobResults.innerHTML='';if(!missingJobDialog.open)missingJobDialog.showModal();try{await api('/jobs/stash-missing-retrieve',{method:'POST',body:JSON.stringify({ids})});pollMissingRetrieve()}catch(e){missingJobStatus.textContent='✕ '+e.message;toast(e.message)}}
// pollMissingRetrieve renders results as they arrive (not only once the
// whole batch finishes) and shows which scene is currently being fetched,
// so a large retrieval no longer looks stalled at 0/N while it runs.
async function pollMissingRetrieve(){try{const j=await api('/jobs/stash-missing-retrieve');missingJobProgress.max=Math.max(j.total||1,1);missingJobProgress.value=(j.retrieved||0)+(j.failed||0);missingJobStatus.textContent=j.running?`Retrieving… ${j.retrieved||0} retrieved · ${j.failed||0} failed of ${j.total||0}${j.current_item?' · '+j.current_item:''}`:j.error?'✕ '+j.error:`Retrieval complete · ${j.retrieved||0} retrieved · ${j.failed||0} failed of ${j.total||0}`;renderMissingJobResults(j.results);if(j.running){setTimeout(pollMissingRetrieve,1000);return}if(!j.error)toast(`Retrieved ${j.retrieved||0}/${j.total||0}${j.failed?' · '+j.failed+' failed':''}`);missingSelection.clear();loadMissingScenes()}catch(e){missingJobStatus.textContent='✕ '+e.message}}
// startMissingApply covers both "Set Monitored Only" (mode monitor_only)
