const logIcons={DEBUG:'🐛',INFO:'ℹ️',WARN:'⚠️',ERROR:'❌'};
// scrapeStatusMeta clearly marks the scrape-validity events introduced in
// Phase 2 (and used for Phase 12's live per-release progress) - the
// "scrape response valid"/"scrape response rejected" log lines carry a
// status field (VALID/BLOCKED/INVALID/ERROR) that would otherwise look
// like any other INFO line.
const scrapeStatusMeta={VALID:{icon:'✅',label:'Valid'},BLOCKED:{icon:'🛡️',label:'Blocked'},INVALID:{icon:'🚫',label:'Invalid'},ERROR:{icon:'⚠️',label:'Error'}};
function renderLogs(){const box=$('#liveLog'),level=$('#logLevelFilter').value,query=$('#logTextFilter').value.trim().toLowerCase(),scrollTop=box.scrollTop;const rows=logRows.filter(x=>{const normalized=String(x.level||'INFO').toUpperCase();if(level!=='ALL'&&normalized!==level)return false;if(!query)return true;return [x.message,...Object.entries(x.fields||{}).flat()].join(' ').toLowerCase().includes(query)});box.innerHTML=rows.map(x=>{const level=String(x.level||'INFO').toUpperCase(),date=new Date(x.time),fields=Object.entries(x.fields||{}).map(([k,v])=>`<span class="logField ${k.toLowerCase()==='error'?'error':''}"><b>${esc(k)}</b>=${esc(String(v))}</span>`).join(''),scrapeStatus=(x.message==='scrape response valid'||x.message==='scrape response rejected')?String((x.fields&&x.fields.status)||'').toUpperCase():'',scrapeMeta=scrapeStatusMeta[scrapeStatus];return `<article class="logEntry" data-level="${esc(level)}" data-scrape="${esc(scrapeStatus)}"><time class="logTime" datetime="${esc(date.toISOString())}" title="${esc(date.toLocaleString())}">${esc(date.toLocaleTimeString())}</time><span class="logLevel">${logIcons[level]||'•'} ${esc(level)}</span><div class="logMessage">${scrapeMeta?`<span class="scrapeBadge scrapeBadge-${esc(scrapeStatus)}">${scrapeMeta.icon} Scrape ${scrapeMeta.label}</span> `:''}${esc(x.message)}${fields?`<div class="logFields">${fields}</div>`:''}</div></article>`}).join('')||`<div class="logEmpty">${logRows.length?'🔎 No log entries match these filters.':'💤 No server log entries yet.'}</div>`;logSummary.textContent=`${rows.length} of ${logRows.length} loaded${logHasMoreOlder?'+':''} entries · updated ${new Date().toLocaleTimeString()}`;if(logFollow.checked)box.scrollTop=box.scrollHeight;else box.scrollTop=scrollTop}
// loadLogs is the fresh "entering the Logs view" load: the newest page,
// discarding whatever was previously accumulated (Phase 13). Incremental
// growth from there on happens via pollLogsTail (new entries) and
// loadOlderLogs (scrolling up for history) so a long-running session never
// has to re-fetch or hold its entire log history at once.
async function loadLogs(){try{const rows=await api('/logs?limit=200');logRows=rows;logOldestSeq=rows.length?rows[0].seq:0;logNewestSeq=rows.length?rows[rows.length-1].seq:0;logHasMoreOlder=rows.length===200;renderLogs()}catch(e){logSummary.textContent='Log unavailable';liveLog.innerHTML=`<div class="logEmpty">⚠️ ${esc(e.message)}</div>`}}
// loadOlderLogs extends the loaded window backward when the user scrolls
// near the top of the log box, instead of ever loading the whole history.
async function loadOlderLogs(){if(logLoadingOlder||!logHasMoreOlder||!logOldestSeq)return;logLoadingOlder=true;try{const older=await api(`/logs?before=${logOldestSeq}&limit=200`);const box=$('#liveLog'),prevHeight=box.scrollHeight;if(older.length){logRows=[...older,...logRows];logOldestSeq=older[0].seq;logHasMoreOlder=older.length===200;if(logRows.length>LOG_CLIENT_CAP){logRows=logRows.slice(0,LOG_CLIENT_CAP);logNewestSeq=logRows[logRows.length-1].seq}renderLogs();box.scrollTop=box.scrollHeight-prevHeight}else{logHasMoreOlder=false}}catch{}finally{logLoadingOlder=false}}
// pollLogsTail fetches only entries newer than what is already loaded
// (Phase 13), instead of re-fetching and replacing the whole visible
// window every tick. Growth is capped client-side (LOG_CLIENT_CAP) by
// dropping the oldest already-loaded rows, which just re-enables
// loadOlderLogs for them rather than losing them (still retained
// server-side up to the ring's own capacity).
async function pollLogsTail(){try{const fresh=await api(`/logs?after=${logNewestSeq}&limit=500`);if(!fresh.length)return;logRows=[...logRows,...fresh];logNewestSeq=fresh[fresh.length-1].seq;if(logRows.length>LOG_CLIENT_CAP){logRows=logRows.slice(logRows.length-LOG_CLIENT_CAP);logOldestSeq=logRows[0].seq;logHasMoreOlder=true}renderLogs()}catch{}}
