async function loadAll(){try{await loadPreferences();if(!applyTemporaryLibrarySearch())applyTemporaryMetadataFilter();initializeAppHistory();await Promise.all([loadVersion(),loadStats(),loadSites(),loadPresets(),loadIntegrationConfig(),loadAccount(),loadDbStatus()]);applyMonitoringSiteTarget();await loadSettings();await loadReleases();if(directReleaseID)await openRelease(directReleaseID,false,null,false);await showPendingChangelog();pollJob();pollStash()}catch(e){toast(e.message)}}
function connectStream(){const ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/api/ws`);ws.onmessage=e=>{try{const x=JSON.parse(e.data);if(x.type==='release'){handleStreamRelease(x.release);loadStats()}}catch{}};ws.onclose=()=>setTimeout(connectStream,3000)}
autoRefreshDownloads.checked=localStorage.getItem('javbeacon.autoRefreshDownloads')!=='false';refreshDownloadActivity.onclick=()=>loadDownloads(true);autoRefreshDownloads.onchange=()=>{localStorage.setItem('javbeacon.autoRefreshDownloads',String(autoRefreshDownloads.checked));toast(autoRefreshDownloads.checked?'Download activity auto-refresh enabled':'Download activity auto-refresh paused')};document.querySelector('[data-view="activity"] svg').innerHTML='<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M9 7V5h6v2M3 12h18M10 12v2h4v-2"/>';advancedSearch.title='Advanced filter conditions';loadAll();connectStream();setInterval(()=>{if(!logsView.hidden)pollLogsTail()},3000);setInterval(()=>{if(autoRefreshDownloads.checked&&!monitoringView.hidden)loadDownloads()},10000);
